settings.custom_liquid:
{% comment %}
  Not Another Wholesale — Reseller Hero Banner
  File: sections/naw-reseller-hero.liquid
{% endcomment %}

<style>
  /* RESELLER HERO — DESKTOP */
  .naw-hero { position: relative; width: 100%; min-height: 420px; display: flex; align-items: center; overflow: hidden; }
  .naw-hero__img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; object-position: center; display: block; z-index: 0; }
  .naw-hero__overlay { position: absolute; inset: 0; background: rgba(0,0,0,0.35); z-index: 1; }
  .naw-hero__inner { position: relative; z-index: 2; width: 100%; max-width: 1400px; margin: 0 auto; padding: 48px 64px; display: flex; align-items: center; justify-content: space-between; gap: 40px; }
  .naw-hero__left { flex: 0 0 240px; }
  .naw-hero__eyebrow { display: block; font-family: 'Poppins', sans-serif; font-size: 11px; font-weight: 700; letter-spacing: 2.5px; text-transform: uppercase; color: rgba(255,255,255,0.6); margin-bottom: 12px; }
  .naw-hero__title { font-family: 'Poppins', sans-serif; font-size: 56px; font-weight: 700; line-height: 1; letter-spacing: -1px; color: #fff; margin: 0 0 32px; text-shadow: 0 2px 12px rgba(0,0,0,0.4); white-space: nowrap; }
  .naw-hero__btn { display: inline-block !important; font-family: 'Poppins', sans-serif !important; background: #fff !important; color: #111 !important; font-size: 12px !important; font-weight: 700 !important; letter-spacing: 1.5px !important; text-transform: uppercase !important; text-decoration: none !important; padding: 14px 28px !important; border-radius: 4px !important; border: none !important; box-shadow: none !important; transition: opacity 0.2s; }
  .naw-hero__btn:hover { opacity: 0.85; }
  .naw-hero__right { flex: 0 0 270px; display: flex; flex-direction: column; }
  .naw-hero__highlight { position: relative; display: inline-block; white-space: nowrap; }
  .naw-hero__highlight::before { content: ''; position: absolute; top: -4px; left: -8px; bottom: -4px; width: 0; background: linear-gradient(to right, #111 60%, rgba(17,17,17,0.85) 80%, rgba(17,17,17,0.4) 92%, transparent 100%); z-index: -1; border-radius: 2px 6px 8px 2px; transition: none; }
  .naw-hero--visible .naw-hero__highlight::before { width: calc(100% + 24px); transition: width 0.6s cubic-bezier(0.4, 0, 0.2, 1); }
  .naw-hero__link { display: flex; align-items: center; justify-content: space-between; padding: 10px 0; border-bottom: 1px solid rgba(255,255,255,0.15); color: #fff; text-decoration: none; font-family: 'Poppins', sans-serif; font-size: 13px; font-weight: 600; letter-spacing: 0.2px; transition: opacity 0.2s; gap: 16px; }
  .naw-hero__link:first-child { border-top: 1px solid rgba(255,255,255,0.15); }
  .naw-hero__link:hover { opacity: 0.65; }

  /* RESELLER HERO — MOBILE */
  @media (max-width: 768px) {
    .naw-hero { min-height: unset; display: block; background: #111; overflow: visible; }
    .naw-hero__img { display: none; }
    .naw-hero__overlay { display: none; }
    .naw-hero__inner { display: none; }
    .naw-hero__mobile-image-wrap { position: relative; display: block; overflow: hidden; }
    .naw-hero__mobile-img { display: block; width: 100%; height: 100%; object-fit: cover; object-position: center; transform: scale(1.2); transform-origin: center center; filter: drop-shadow(0px 25px 50px rgba(0,0,0,0.15)); }
    .naw-hero__mobile-overlay { position: absolute; inset: 0; background: rgba(0,0,0,0.45); z-index: 1; }
    .naw-hero__mobile-content { position: absolute; inset: 0; z-index: 2; display: flex; flex-direction: column; justify-content: space-between; padding: 35px 0 0; gap: 0; }
    .naw-hero__mobile-top { display: flex; flex-direction: column; padding: 0 16px; }
    .naw-hero__mobile-top .naw-hero__title { margin-bottom: 0; }
    .naw-hero__eyebrow { display: block; font-family: 'Poppins', sans-serif; font-size: 10px; font-weight: 700; letter-spacing: 2.5px; text-transform: uppercase; color: rgba(255,255,255,0.6); margin-bottom: 4px; }
    .naw-hero__title { font-family: 'Poppins', sans-serif; font-size: 44px; font-weight: 700; line-height: 0.95; letter-spacing: -1px; color: #fff; margin: 0 0 0 -2px; text-shadow: 0 2px 12px rgba(0,0,0,0.4); white-space: normal; }
    .naw-hero__highlight::before { z-index: -1; }
    .naw-hero__mobile-links { display: grid; grid-template-columns: 1fr 1fr; gap: 0; border-top: 1px solid rgba(255,255,255,0.15); margin-top: auto; }
    .naw-hero__mobile-link { display: flex; align-items: center; justify-content: center; padding: 10px 12px; border-bottom: 1px solid rgba(255,255,255,0.12); color: #fff; text-decoration: none; font-family: 'Poppins', sans-serif; font-size: 11px; font-weight: 900; text-shadow: 0 1px 6px rgba(0,0,0,0.7); letter-spacing: 0.04em; text-transform: uppercase; background: transparent; transition: opacity 0.2s; text-align: center; }
    .naw-hero__mobile-link:nth-child(odd) { border-right: 1px solid rgba(255,255,255,0.12); }
    .naw-hero__mobile-link:hover { opacity: 0.65; }
    .naw-hero__mobile-link svg { display: none; }
    .naw-hero__mobile-btn-wrap { background: #111 url('https://cdn.shopify.com/s/files/1/0810/4090/0375/files/concrete_button_background.png?v=1773614852') center/cover no-repeat; padding: 20px 16px; margin-top: 0; }
    .naw-hero__btn { display: block !important; width: 100% !important; text-align: center !important; padding: 18px 28px !important; font-size: 11px !important; letter-spacing: 2px !important; border-radius: 4px !important; background: #fff !important; color: #111 !important; }
  }
  @media (min-width: 769px) {
    .naw-hero__mobile-image-wrap { display: none; }
    .naw-hero__mobile-btn-wrap { display: none; }
    .naw-hero__btn--desktop { display: inline-block !important; }
  }
</style>

<div class="naw-hero">

  <!-- DESKTOP: background image + overlay -->
  <img class="naw-hero__img" src="https://cdn.shopify.com/s/files/1/0810/4090/0375/files/BEGIN_YOUR_RESELLING_JOURNEY_TODAY.._NOTANOTHERWHOLESALE.png?v=1773416550" alt="Reseller Packs" loading="eager">
  <div class="naw-hero__overlay"></div>

  <!-- DESKTOP: inner content -->
  <div class="naw-hero__inner">
    <div class="naw-hero__left">
      <span class="naw-hero__eyebrow">Best Seller</span>
      <h2 class="naw-hero__title"><span class="naw-hero__highlight">RESELLER</span><br>PACKS</h2>
      <a href="https://notanotherwholesale.com/collections/reseller-bundles" class="naw-hero__btn naw-hero__btn--desktop" style="margin-top:32px;">BECOME A RESELLER &#8594;</a>
    </div>
    <div class="naw-hero__right">
      <a href="https://notanotherwholesale.com/products/30-piece-reseller-box" class="naw-hero__link">
        <span>VINTED DEPOP RESELLER BOXES</span>
        <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="rgba(255,255,255,0.5)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 18 15 12 9 6"/></svg>
      </a>
      <a href="https://notanotherwholesale.com/products/premium-reseller-box-x25" class="naw-hero__link">
        <span>PREMIUM RESELLER BOXES</span>
        <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="rgba(255,255,255,0.5)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 18 15 12 9 6"/></svg>
      </a>
      <a href="https://notanotherwholesale.com/products/basic-reseller-box-x30" class="naw-hero__link">
        <span>BASIC RESELLER BOXES</span>
        <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="rgba(255,255,255,0.5)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 18 15 12 9 6"/></svg>
      </a>
      <a href="https://notanotherwholesale.com/products/sample-pack" class="naw-hero__link">
        <span>SAMPLE RESELLER PACKS</span>
        <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="rgba(255,255,255,0.5)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 18 15 12 9 6"/></svg>
      </a>
    </div>
  </div>

  <!-- MOBILE: portrait image with title + 2x2 links overlaid -->
  <div class="naw-hero__mobile-image-wrap">
    <img class="naw-hero__mobile-img" src="https://cdn.shopify.com/s/files/1/0810/4090/0375/files/mobile_version_-_reseller_packs_hero.png?v=1773420900" alt="Reseller Packs" loading="eager">
    <div class="naw-hero__mobile-overlay"></div>
    <div class="naw-hero__mobile-content">
      <div class="naw-hero__mobile-top">
        <span class="naw-hero__eyebrow">BEST SELLER</span>
        <h2 class="naw-hero__title"><span class="naw-hero__highlight">RESELLER</span><br>PACKS</h2>
      </div>
      <div class="naw-hero__mobile-links">
        <a href="https://notanotherwholesale.com/products/30-piece-reseller-box" class="naw-hero__mobile-link">shop VINTED DEPOP</a>
        <a href="https://notanotherwholesale.com/products/sample-pack" class="naw-hero__mobile-link">shop SAMPLe</a>
        <a href="https://notanotherwholesale.com/products/premium-reseller-box-x25" class="naw-hero__mobile-link"> shop PREMIUM</a>
        <a href="https://notanotherwholesale.com/products/basic-reseller-box-x30" class="naw-hero__mobile-link">shop BASIC</a>
      </div>
    </div>
  </div>

  <!-- MOBILE: CTA below image -->
  <div class="naw-hero__mobile-btn-wrap">
    <a href="https://notanotherwholesale.com/collections/reseller-bundles" class="naw-hero__btn">BECOME A RESELLER &#8594;</a>
  </div>

</div>

<script>
(function(){
  var hero = document.querySelector('.naw-hero');
  if (!hero) return;
  var obs = new IntersectionObserver(function(entries){
    entries.forEach(function(e){
      if (e.isIntersecting) {
        setTimeout(function(){ hero.classList.add('naw-hero--visible'); }, 200);
        obs.disconnect();
      }
    });
  }, { threshold: 0.3 });
  obs.observe(hero);
}());
</script>
